insert into public.recipes (id, status, cover_image, prep_minutes, cook_minutes, servings, video_url, family_id, variant_label, variant_image, related_post_ids) values ('recipe-zupa-pomidorowa', 'published', 'https://kdrbtwwhmzszzukcffsu.supabase.co/storage/v1/object/public/recipe-media/recipes/recipe-zupa-pomidorowa/1dc1deb5-b454-41f4-a58d-5561a4cf7613.webp', 15, 35, 4, null, null, '{}'::jsonb, '', array['post-polnische-suppen', 'post-smietana-schmand', 'post-sonntagsessen']::text[]) on conflict (id) do update set status = excluded.status, cover_image = excluded.cover_image, prep_minutes = excluded.prep_minutes, cook_minutes = excluded.cook_minutes, servings = excluded.servings, video_url = excluded.video_url, family_id = excluded.family_id, variant_label = excluded.variant_label, variant_image = excluded.variant_image, related_post_ids = excluded.related_post_ids, updated_at = now();
insert into public.recipe_translations (recipe_id, locale, title, slug, excerpt, steps, article, seo_title, seo_description) values ('recipe-zupa-pomidorowa', 'de', 'Zupa pomidorowa', 'zupa-pomidorowa', 'Zupa pomidorowa ist die polnische Alltags-Tomatensuppe mit Reis oder Nudeln und Śmietana, deutlich anders als Barszcz und Ogórkowa.', '[{"text":"Eine leichte Brühe erhitzen, oft aus Resten von [Rosół](/de/rezepte/rosol), und Zwiebel sowie Karotte kurz darin anschwitzen oder mitkochen.","tip":"Das ist eine Alltags-Suppe und keine klare Festtagsbrühe. Den Überblick über die ganze Familie gibt der Beitrag zu [polnischen Suppen](/de/blog/polnische-suppen)."},{"text":"Tomatensauce oder passierte Tomaten einrühren und 10 bis 15 Minuten sanft köcheln lassen. Reis oder kleine Nudeln separat garen oder direkt in der Suppe weich kochen.","tip":"Das ist weder [Barszcz](/de/rezepte/barszcz-czerwony) mit roter Bete noch [Ogórkowa](/de/rezepte/ogorkowa) mit Kiszone-Gurke, sondern eine eigene, mild-tomatige Linie."},{"text":"Mit Salz, Pfeffer und etwas Zucker oder Basilikum abschmecken, dann vom Herd nehmen und die temperierte Śmietana einrühren.","tip":"Temperiere die Śmietana wie im Beitrag zu [Śmietana und Schmand](/de/blog/smietana-schmand) beschrieben, sonst flockt sie beim Einrühren in die heiße Suppe."},{"text":"Heiß mit Dill oder Petersilie servieren, als leichter Mittagsteller oder als Starter im Rahmen eines [polnischen Sonntagsessens](/de/blog/sonntagsessen-polnisch)."}]'::jsonb, 'Zupa pomidorowa, mild-tomatig, cremig mit Śmietana, alltagsleicht. Die Tomate kam im 16. Jahrhundert mit Königin Bona Sforza nach Polen, wurde aber jahrhundertelang nur als Zierpflanze angebaut, weil man sie für giftig hielt. Erst zu Beginn des 20. Jahrhunderts landete die frische Tomate auf polnischen Tellern, und Tomatensuppen-Rezepte finden sich in polnischen Kochbüchern bereits im 19. Jahrhundert. Ihren wahren Durchbruch erlebte Zupa pomidorowa aber in der Zeit der Volksrepublik, als preiswertes und lange haltbares Tomatenmark aus Fabriken wie Pudliszki zur festen Größe in Suppenküchen und Schulkantinen wurde. Traditionell baut man die Suppe auf einer hellen Hühner- oder Gemüsebrühe auf, oft direkt aus Resten von [Rosół](/de/rezepte/rosol), verfeinert mit Śmietana, Reis oder kleinen Nudeln. Das ist bewusst kein Festtags-[Barszcz](/de/rezepte/barszcz-czerwony) mit roter Bete, keine kiszone [Ogórkowa](/de/rezepte/ogorkowa) und kein klarer [Rosół](/de/rezepte/rosol) ohne Tomate. Im Überblick [Polnische Suppen](/de/blog/polnische-suppen) gehört Pomidorowa zur ruhigen Alltagslinie, während der Guide selbst der breite Überblick bleibt.

## Einkaufen und kochen

Nimm passierte Tomaten oder eine gute Tomatensauce, Brühe (Huhn oder Gemüse), Zwiebel und Karotte sowie Reis oder kleine Nudeln, Śmietana oder Schmand und Dill. Passata und manchmal die etwas rundere Sauce findest du im [Polenladen](/de/blog/polenladen-einkaufen). Eine klare Brühe allein ist [Rosół](/de/rezepte/rosol), eine Dillsuppe ohne Tomate ist [Koperkowa](/de/rezepte/koperkowa).

Baue zuerst die Brühe auf oder nutze Reste von Rosół, rühre dann die Tomaten ein und lasse alles sanft köcheln, ohne dass die Suppe sprudelt. Koche Reis oder Nudeln nicht zu weich, sie ziehen in der Schüssel noch nach und werden sonst matschig. Temperiere die Śmietana, bevor du sie nach dem Herunternehmen vom Herd unterziehst, sonst flockt sie in der heißen Suppe. Säure und Süße gehören ans Ende: Eine Prise Zucker kann industrielle Tomaten runden, ersetzt aber keine gute Passata. Das Brühe-Gefühl kann an [Rosół-Technik](/de/blog/rosol-technik) erinnern, im Mittelpunkt bleibt hier aber die Pomidorowa.

In Deutschland ist Pomidorowa oft die Suppe, die Kinder von klein auf kennen und die Erwachsene aus Rosół-Resten retten, ein Topf reicht für zwei Mittage. Den Überblick ohne einen weiteren Guide gibt [Polnische Suppen](/de/blog/polnische-suppen). Wer regelmäßig Brühe auf Vorrat kocht, hat die Basis bereits fertig, Tomate sowie Reis oder Nudeln machen dann den eigentlichen Charakter aus. Es braucht keine bestimmte polnische Flaschenmarke, eine gute Passata reicht völlig.

## Am Tisch

Heiß mit Dill oder Petersilie servieren, oft mit extra Śmietana direkt am Tisch. Als leichter Hauptgang oder als Vorsuppe vor dem Fleisch passt sie in die Menükultur des [Sonntagsessens](/de/blog/sonntagsessen-polnisch). Halte auf dem Tisch klar: Der klare [Barszcz](/de/rezepte/barszcz-czerwony) gehört zu Wigilia und Uszka, die saure [Ogórkowa](/de/rezepte/ogorkowa) zu Kiszone, und die klare [Rosół](/de/rezepte/rosol)-Schale bleibt ohne Tomate. Reste gut gekühlt aufbewahren und beim Aufwärmen die Śmietana nicht erneut hart aufkochen.

Am häufigsten wird Pomidorowa mit [Barszcz](/de/rezepte/barszcz-czerwony) oder mit [Ogórkowa](/de/rezepte/ogorkowa) verwechselt, obwohl beide einen ganz anderen Charakter haben. Śmietana kochend einzurühren lässt sie sofort flocken, und zu lange gekochter Reis wird schnell breiig statt bissfest. Wer zu wenig abschmeckt, verpasst genau die milde Säure, die den polnischen Charakter dieser Tomatensuppe ausmacht.

Manche Häuser kochen sie mit Reis, andere mit Nudeln oder mit mehr Gemüse, eine vegetarische Version gelingt gut auf klarem Gemüsefond. Den Überblick gibt [Polnische Suppen](/de/blog/polnische-suppen), mehr zur Śmietana der Beitrag [Śmietana und Schmand](/de/blog/smietana-schmand). Der klare Nachbar bleibt [Rosół](/de/rezepte/rosol) mitsamt der [Rosół-Technik](/de/blog/rosol-technik), der Festtags-Nachbar mit roter Bete ist [Barszcz](/de/rezepte/barszcz-czerwony), und die kiszone Linie vertritt [Ogórkowa](/de/rezepte/ogorkowa).', 'Zupa pomidorowa Rezept | Polnische Tomatensuppe | Alemniam', 'Zupa pomidorowa, polnische Tomatensuppe mit Reis oder Nudeln und Śmietana. Bilingual, klar getrennt von Barszcz und Ogórkowa.') on conflict (recipe_id, locale) do update set title = excluded.title, slug = excluded.slug, excerpt = excluded.excerpt, steps = excluded.steps, article = excluded.article, seo_title = excluded.seo_title, seo_description = excluded.seo_description;
insert into public.recipe_translations (recipe_id, locale, title, slug, excerpt, steps, article, seo_title, seo_description) values ('recipe-zupa-pomidorowa', 'pl', 'Zupa pomidorowa', 'zupa-pomidorowa', 'Zupa pomidorowa to polska zupa codzienna z ryżem lub makaronem i śmietaną, jasno inna niż barszcz i ogórkowa.', '[{"text":"Podgrzej lekki wywar, często z resztek [rosołu](/pl/rezepte/rosol), i krótko zeszklij w nim albo dogotuj cebulę i marchew.","tip":"To zupa na co dzień, nie klarowny wywar świąteczny. Przegląd całej rodziny zup daje artykuł o [polskich zupach](/pl/blog/polskie-zupy)."},{"text":"Wymieszaj przecier lub passatę pomidorową i gotuj łagodnie 10 do 15 minut. Ryż lub drobny makaron ugotuj osobno albo wprost w zupie do miękkości.","tip":"To ani [barszcz](/pl/rezepte/barszcz-czerwony) z burakiem, ani [ogórkowa](/pl/rezepte/ogorkowa) z ogórkiem kiszonym, tylko własna, łagodnie pomidorowa linia."},{"text":"Dopraw solą, pieprzem i odrobiną cukru lub bazylii, zdejmij z ognia i włącz ocieploną śmietanę.","tip":"Zahartuj śmietanę zgodnie z opisem w artykule [śmietana czy Schmand](/pl/blog/smietana-czy-schmand), inaczej zważy się w gorącej zupie."},{"text":"Podawaj gorącą z koperkiem lub pietruszką, jako lekki obiad albo starter w ramach [obiadu niedzielnego](/pl/blog/obiad-niedzielny)."}]'::jsonb, 'Zupa pomidorowa, łagodnie pomidorowa, kremowa ze śmietaną, codzienna. Pomidor trafił do Polski w XVI wieku dzięki królowej Bonie Sforzy, ale przez wieki uprawiano go głównie jako rośliny ozdobne, bo uważano go za trujący. Świeży pomidor pojawił się na polskich talerzach dopiero na początku XX wieku, choć przepisy na zupę pomidorową można znaleźć w polskich książkach kucharskich już w XIX wieku. Prawdziwy przełom zupa pomidorowa przeżyła w czasach Polskiej Rzeczpospolitej Ludowej, gdy tani i trwały koncentrat pomidorowy z fabryk jak Pudliszki stał się podstawą stołówek i domowych obiadów. Tradycyjnie zupę buduje się na jasnym wywarze drobiowym lub warzywnym, często wprost z resztek [rosołu](/pl/rezepte/rosol), i dopełnia śmietaną, ryżem lub drobnym makaronem. To świadomie nie świąteczny [barszcz](/pl/rezepte/barszcz-czerwony) z burakiem, nie kiszona [ogórkowa](/pl/rezepte/ogorkowa) i nie klarowny [rosół](/pl/rezepte/rosol) bez pomidora. W przeglądzie [polskich zup](/pl/blog/polskie-zupy) pomidorowa należy do spokojnej linii codziennej, a sam przewodnik zostaje szerokim przeglądem.

## Zakupy i gotowanie

Weź przecier lub dobrą passatę, wywar (drobiowy lub warzywny), cebulę i marchew oraz ryż lub drobny makaron, śmietanę i koperek. Passata, a czasem trochę bardziej okrągły sos, znajdziesz w [sklepie polskim](/pl/blog/sklep-polski-zakupy). Sam klarowny wywar to [rosół](/pl/rezepte/rosol), zupa koperkowa bez pomidora to [koperkowa](/pl/rezepte/koperkowa).

Najpierw zbuduj wywar albo skorzystaj z resztek rosołu, wmieszaj pomidory i gotuj łagodnie, bez gwałtownego wrzenia. Ryżu lub makaronu nie rozgotowuj za mocno, dociągną jeszcze w misce, inaczej zrobią się papkowate. Śmietanę ociepl, zanim wmieszasz ją po zdjęciu zupy z ognia, inaczej zważy się w gorącym płynie. Kwas i słodycz dodaj na końcu: szczypta cukru zaokrągli przemysłowe pomidory, ale nie zastąpi dobrej passaty. Wyczucie wywaru może przypominać [technikę rosołu](/pl/blog/jak-ugotowac-rosol), w centrum zostaje jednak pomidorowa.

W Niemczech pomidorowa bywa zupą, którą dzieci znają od małego, a dorośli ratują nią resztki rosołu, jeden garnek wystarcza na dwa obiady. Przegląd bez kolejnego przewodnika daje artykuł [polskie zupy](/pl/blog/polskie-zupy). Kto regularnie gotuje wywar na zapas, ma gotową bazę, a pomidor oraz ryż lub makaron budują właściwy charakter. Nie trzeba konkretnej polskiej marki w butelce, dobra passata w pełni wystarcza.

## Przy stole

Podawaj gorącą z koperkiem lub pietruszką, często z dodatkową śmietaną na stole. Jako lekki główny posiłek albo przystawka przed mięsem wpisuje się w kulturę menu [obiadu niedzielnego](/pl/blog/obiad-niedzielny). Na stole trzymaj jasność: klarowny [barszcz](/pl/rezepte/barszcz-czerwony) należy do Wigilii i uszek, kwaśna [ogórkowa](/pl/rezepte/ogorkowa) do kiszonek, a klarowna miska [rosołu](/pl/rezepte/rosol) zostaje bez pomidora. Resztki przechowuj dobrze schłodzone, a przy odgrzewaniu nie doprowadzaj śmietany ponownie do wrzenia.

Najczęściej pomidorową myli się z [barszczem](/pl/rezepte/barszcz-czerwony) albo z [ogórkową](/pl/rezepte/ogorkowa), choć obie mają zupełnie inny charakter. Wlewanie śmietany do wrzątku powoduje jej natychmiastowe zważenie, a zbyt długo gotowany ryż robi się papkowaty, zamiast zostać jędrny. Kto za mało dopraw kwasu, przegapia właśnie tę łagodną kwaskowość, która nadaje tej zupie polski charakter.

Niektóre domy gotują ją z ryżem, inne z makaronem albo z większą ilością warzyw, wegetariańska wersja dobrze wychodzi na klarownym wywarze warzywnym. Przegląd daje [polskie zupy](/pl/blog/polskie-zupy), więcej o śmietanie artykuł [śmietana czy Schmand](/pl/blog/smietana-czy-schmand). Klarowny sąsiad zostaje przy [rosole](/pl/rezepte/rosol) razem z [techniką rosołu](/pl/blog/jak-ugotowac-rosol), świątecznym sąsiadem z burakiem jest [barszcz](/pl/rezepte/barszcz-czerwony), a linię kiszoną reprezentuje [ogórkowa](/pl/rezepte/ogorkowa).', 'Zupa pomidorowa przepis | Zupa z pomidorów | Alemniam', 'Zupa pomidorowa, z ryżem lub makaronem i śmietaną. Dwujęzycznie, jasno osobno od barszczu i ogórkowej.') on conflict (recipe_id, locale) do update set title = excluded.title, slug = excluded.slug, excerpt = excluded.excerpt, steps = excluded.steps, article = excluded.article, seo_title = excluded.seo_title, seo_description = excluded.seo_description;
